/**
 * Runtime 自有方法（非 app-server 透传部分）与 Runtime 事件。
 * 命名空间：runtime/*、auth/*、blender/*、workspace/*、artifact/*、tools/*、print/*，以及自有 skills 安装方法。
 */
import { z } from 'zod';
import { Hi3dModelSource, ModelRetry, RetryQuota, modelRetryMethods } from './model-retry';
import { SkillTelemetryEvent } from './skill-telemetry';
import { RuntimePhase } from './envelope';
import { DynamicToolSpec, ImageClassificationResult, ModelName } from './dynamic-tools';
import { SkillInstallRequest, SkillInstallation, InstalledUserSkill, UserSkillId } from './skills';
import { SkillInstance, SkillUseSummary, EffectiveSkill, SkillDraft, SkillCaptureSuggestion, skillCommunityMethods, skillCreationMethods } from './skill-community';

const WorkspaceName = z.string().trim().min(1).max(120).regex(/^[^\r\n\0]+$/, 'Workspace name must not contain newline or null characters');
/** Shared accounting/display interval; temporarily lower this one value for testing. */
export const CONVERSATION_CREDIT_STEP = 400;
/** Conversation credit reminders continue automatically if the user does not respond. */
export const CONVERSATION_CREDIT_AUTO_CONTINUE_SECONDS = 60;
// ── 公共对象 ────────────────────────────────────────────────────

/** 工作区里的一个 glb 版本文件，如 hi3d-aaa_2.glb；版本按文件名分组，模型提交时按内容去重 */
export const ModelFile = z.object({
  name: z.string(),
  index: z.number().int().positive(),
  fileName: z.string(),
  /** 工作区内相对路径（目前就是 fileName，摊平放在工作区根目录） */
  path: z.string(),
  size: z.number().int().nonnegative(),
  updatedAt: z.number(),
  threadId: z.string().optional(),
  turnId: z.string().optional(),
  note: z.string().optional(),
  /** 此版本的形态分类；缺省表示未分类，tag4: null 表示使用通用策略。 */
  tags: ImageClassificationResult.optional(),
  source: Hi3dModelSource.optional(),
});
export type ModelFile = z.infer<typeof ModelFile>;

/** 一个模型家族（同名前缀）的全部版本，versions 按 index 升序 */
export const Model = z.object({
  name: z.string(),
  versions: z.array(ModelFile),
  latest: ModelFile,
});
export type Model = z.infer<typeof Model>;

export const Workspace = z.object({
  assetId: z.string(),
  name: z.string(),
  /** 工作区目录绝对路径；也是 codex thread 的 cwd */
  cwd: z.string(),
  threadIds: z.array(z.string()),
  createdAt: z.number(),
  updatedAt: z.number(),
  /** cwd 不存在或不再是托管目录时由 list() 标出，供 UI 提示；不落盘 */
  missing: z.boolean().optional(),
  projectId: z.string().nullable().optional(),
});
export type Workspace = z.infer<typeof Workspace>;

export const ArtifactRole = z.enum([
  'studio-save',
  'blender-output',
  'export-3mf',
  'export-zip',
  'export-glb',
  'layout',
  'screenshot',
  'report',
  'other',
]);
export type ArtifactRole = z.infer<typeof ArtifactRole>;

export const Artifact = z.object({
  artifactId: z.string(),
  assetId: z.string(),
  /** 工作区内相对路径 */
  path: z.string(),
  role: ArtifactRole,
  size: z.number().int().nonnegative(),
  mimeType: z.string().optional(),
  sha256: z.string().optional(),
  createdAt: z.number(),
  threadId: z.string().optional(),
  turnId: z.string().optional(),
});
export type Artifact = z.infer<typeof Artifact>;

/** Desktop-owned per-turn execution graph. This is deliberately separate from pcg.board.v1. */
export const WorkflowLocale = z.enum(['en', 'zh', 'ja', 'de', 'es', 'fr', 'id', 'ko', 'pt', 'uk']);
export type WorkflowLocale = z.infer<typeof WorkflowLocale>;

export const WorkflowNode = z.object({
  id: z.string(),
  parentId: z.string().nullable(),
  label: z.string(),
  /** Language of this label. Absent on graphs saved before localization. */
  labelLocale: WorkflowLocale.optional(),
  role: z.enum(['agent', 'subagent', 'local', 'step']),
  status: z.enum(['pending', 'running', 'completed', 'failed', 'skipped', 'interrupted']),
  optional: z.boolean(),
  entry: z.string().nullable(),
});
export type WorkflowNode = z.infer<typeof WorkflowNode>;

export const WorkflowEdge = z.object({
  from: z.string(),
  to: z.string(),
  kind: z.enum(['advance', 'contains', 'spawn', 'rollback']),
});
export type WorkflowEdge = z.infer<typeof WorkflowEdge>;

export const WorkflowArtifact = z.object({
  id: z.string(),
  nodeId: z.string().nullable(),
  kind: z.enum(['model', 'image', 'file', 'link']),
  label: z.string(),
  assetId: z.string().nullable(),
  fileName: z.string().nullable(),
  path: z.string().nullable(),
  url: z.string().nullable(),
  mimeType: z.string().nullable(),
  createdAt: z.number(),
});
export type WorkflowArtifact = z.infer<typeof WorkflowArtifact>;

export const WorkflowGraph = z.object({
  schema: z.literal('runtime.workflow.v1'),
  graphId: z.string(),
  threadId: z.string(),
  turnId: z.string().nullable(),
  continuedFromGraphId: z.string().optional(),
  revision: z.number().int().positive(),
  title: z.string(),
  /** User-message language for this turn, independent of the app setting. */
  locale: WorkflowLocale.optional(),
  titleLocale: WorkflowLocale.optional(),
  source: z.enum(['generic', 'explicit-skill', 'agent-plan']),
  skillName: z.string().nullable(),
  layout: z.enum(['linear', 'tree']),
  status: z.enum(['planning', 'running', 'completed', 'failed', 'interrupted']),
  nodes: z.array(WorkflowNode),
  edges: z.array(WorkflowEdge),
  artifacts: z.array(WorkflowArtifact),
  createdAt: z.number(),
  updatedAt: z.number(),
});
export type WorkflowGraph = z.infer<typeof WorkflowGraph>;

export const PrintChannel = z.enum(['slicer', 'device', 'direct']);
export const PrintJobStatus = z.enum([
  'file-ready',
  'handed-to-slicer',
  'uploading',
  'device-received',
  'printing',
  'failed',
  'unknown',
]);
export const PrintJob = z.object({
  printJobId: z.string(),
  assetId: z.string(),
  artifactId: z.string(),
  channel: PrintChannel,
  target: z.string().optional(),
  status: PrintJobStatus,
  message: z.string().optional(),
  createdAt: z.number(),
  updatedAt: z.number(),
});
export type PrintJob = z.infer<typeof PrintJob>;

export const ComponentInfo = z.object({
  available: z.boolean(),
  version: z.string().optional(),
  path: z.string().optional(),
});

export const BlenderInstallState = z.enum([
  'idle',
  'checking',
  'downloading',
  'verifying',
  'installing',
  'validating',
  'ready',
  'failed',
  'cancelled',
]);
export type BlenderInstallState = z.infer<typeof BlenderInstallState>;

export const BlenderStatus = z.object({
  available: z.boolean(),
  path: z.string().optional(),
  source: z.enum(['environment', 'managed', 'system', 'path', 'missing']),
  installSupported: z.boolean(),
  platform: z.string(),
  arch: z.string(),
  targetSeries: z.literal('4.5'),
  version: z.string().optional(),
  state: BlenderInstallState,
  progress: z.number().min(0).max(1).nullable(),
  downloadedBytes: z.number().int().nonnegative().optional(),
  totalBytes: z.number().int().positive().optional(),
  message: z.string(),
  restartRequired: z.boolean(),
  failureReason: z.enum(['windows-integrity-policy']).optional(),
});
export type BlenderStatus = z.infer<typeof BlenderStatus>;

// ── 方法定义 ────────────────────────────────────────────────────

export const runtimeMethods = {
  ...modelRetryMethods,
  ...skillCreationMethods,
  'skills/installations': skillCommunityMethods['skills/installations'],
  'skills/clearInstallLog': skillCommunityMethods['skills/clearInstallLog'],
  'skills/setCandidateName': skillCommunityMethods['skills/setCandidateName'],
  'skills/analyzeInstall': skillCommunityMethods['skills/analyzeInstall'],
  'skills/detail': skillCommunityMethods['skills/detail'],
  'skills/setEnabled': skillCommunityMethods['skills/setEnabled'],
  'skills/setInvocationPolicy': skillCommunityMethods['skills/setInvocationPolicy'],
  'skills/repair': skillCommunityMethods['skills/repair'],
  'skills/prepareUpdate': skillCommunityMethods['skills/prepareUpdate'],
  'skills/checkUpdate': skillCommunityMethods['skills/checkUpdate'],
  'skills/effective': skillCommunityMethods['skills/effective'],
  'skills/install': {
    params: SkillInstallRequest,
    result: z.object({ installationId: z.string(), installation: SkillInstallation }),
  },
  'skills/installStatus': {
    params: z.object({ installationId: z.string().min(1) }),
    result: z.object({ installation: SkillInstallation }),
  },
  'skills/selectInstall': {
    params: z.object({ installationId: z.string().min(1), subdir: z.string().max(1024) }),
    result: z.object({ installation: SkillInstallation }),
  },
  'skills/confirmInstall': {
    params: z.object({ installationId: z.string().min(1), confirmations: z.array(z.object({ candidateId: z.string().min(1), confirmationToken: z.string().min(1) }).strict()).min(1).max(50) }).strict(),
    result: z.object({ installation: SkillInstallation }),
  },
  'skills/cancelInstall': {
    params: z.object({ installationId: z.string().min(1) }),
    result: z.object({ cancelled: z.boolean(), installation: SkillInstallation }),
  },
  'skills/installed': {
    params: z.object({}).optional(),
    result: z.object({ skills: z.array(SkillInstance), usage: z.record(z.string(), SkillUseSummary).optional(), official: z.array(EffectiveSkill).optional(), needsRepair: z.array(z.string()).optional() }),
  },
  'skills/uninstall': {
    params: z.union([z.object({ instanceId: z.string().min(1), expectedRevisionId: z.string().min(1) }).strict(), z.object({ skillId: UserSkillId }).strict()]),
    result: z.object({ instanceId: z.string(), removed: z.boolean() }),
  },
  'runtime/hello': {
    params: z.object({
      protocolVersion: z.string(),
      client: z.object({ name: z.string(), version: z.string() }),
    }),
    result: z.object({
      protocolVersion: z.string(),
      runtime: z.object({ name: z.string(), version: z.string(), mock: z.boolean().optional() }),
      codex: ComponentInfo,
      blender: ComponentInfo,
      python: ComponentInfo,
      platform: z.string(),
      workspacesRoot: z.string(),
      capabilities: z.object({
        appServer: z.boolean(),
        dynamicTools: z.boolean(),
        sandbox: z.enum(['seatbelt', 'landlock', 'windows', 'none', 'unknown']),
      }),
    }),
  },
  'runtime/status': {
    params: z.object({}).optional(),
    result: z.object({
      phase: RuntimePhase,
      codex: z.object({ running: z.boolean(), pid: z.number().optional(), restarts: z.number() }),
      lastError: z.string().nullable(),
      paths: z.object({
        codexHome: z.string(),
        workspacesRoot: z.string(),
        logs: z.string(),
      }),
    }),
  },
  'auth/setCredential': {
    params: z.object({
      provider: z.enum(['model']),
      token: z.string(),
      expiresAt: z.number().optional(),
      accountId: z.string().optional(),
    }),
    result: z.object({ applied: z.boolean(), restartRequired: z.boolean() }),
  },
  'blender/status': {
    params: z.object({}).optional(),
    result: BlenderStatus,
  },
  'blender/install': {
    params: z.object({}).optional(),
    result: z.object({ started: z.boolean(), status: BlenderStatus }),
  },
  'blender/usePath': {
    params: z.object({ path: z.string().min(1).max(4096) }),
    result: z.object({ status: BlenderStatus }),
  },
  'blender/cancelInstall': {
    params: z.object({}).optional(),
    result: z.object({ cancelled: z.boolean(), status: BlenderStatus }),
  },
  'workspace/list': {
    params: z.object({}).optional(),
    result: z.object({ workspaces: z.array(Workspace) }),
  },
  'workspace/create': {
    params: z.object({ name: WorkspaceName }).strict(),
    result: z.object({ workspace: Workspace }),
  },
    'workspace/acquireDraft': {
      params: z.object({ name: WorkspaceName, draftId: z.string().uuid() }),
      result: z.object({ workspace: Workspace }),
    },

  'workspace/open': {
    params: z.object({ assetId: z.string() }),
    result: z.object({ workspace: Workspace, models: z.array(Model) }),
  },
  'workspace/remove': {
    params: z.object({ assetId: z.string() }),
    result: z.object({ assetId: z.string() }),
  },
  'workspace/import': {
    params: z.object({
      assetId: z.string(),
      /** 模型家族名，如 "aaa"；落盘文件自动带 hi3d- 前缀 */
      name: ModelName,
      /** 绝对路径；由 Main 文件对话框或生成服务下载得到 */
      sourcePath: z.string(),
    }),
    result: z.object({ workspace: Workspace, file: ModelFile }),
  },
  'workspace/models': {
    params: z.object({ assetId: z.string() }),
    result: z.object({ models: z.array(Model) }),
  },
  'workspace/commit': {
    params: z.object({
      assetId: z.string(),
      artifactId: z.string(),
      /** 模型家族名；落盘文件自动带 hi3d- 前缀 */
      name: ModelName,
      threadId: z.string().optional(),
      turnId: z.string().optional(),
      note: z.string().optional(),
    }),
    result: z.object({ workspace: Workspace, file: ModelFile }),
  },
  'artifact/register': {
    params: z.object({
      assetId: z.string(),
      /** 工作区内相对路径（Main 文件桥已写入） */
      path: z.string(),
      role: ArtifactRole,
      mimeType: z.string().optional(),
      threadId: z.string().optional(),
      turnId: z.string().optional(),
    }),
    result: z.object({ artifact: Artifact }),
  },
  'workflow/read': {
    params: z.object({ threadId: z.string().min(1) }),
    result: z.object({ graphs: z.array(WorkflowGraph) }),
  },
  'tools/dynamicSpecs': {
    params: z.object({}).optional(),
    result: z.object({ tools: z.array(DynamicToolSpec) }),
  },
  'print/send': {
    params: z.object({
      assetId: z.string(),
      artifactId: z.string(),
      channel: PrintChannel,
      target: z.string().optional(),
    }),
    result: z.object({ printJob: PrintJob }),
  },
  'print/status': {
    params: z.object({ printJobId: z.string() }),
    result: z.object({ printJob: PrintJob }),
  },
} as const;

export type RuntimeMethodName = keyof typeof runtimeMethods;
export type RuntimeParams<M extends RuntimeMethodName> = z.infer<(typeof runtimeMethods)[M]['params']>;
export type RuntimeResult<M extends RuntimeMethodName> = z.infer<(typeof runtimeMethods)[M]['result']>;

export const RUNTIME_METHOD_NAMES = Object.keys(runtimeMethods) as RuntimeMethodName[];

export function isRuntimeMethod(method: string): method is RuntimeMethodName {
  return Object.prototype.hasOwnProperty.call(runtimeMethods, method);
}

// ── Runtime 事件（notification） ─────────────────────────────────

export const runtimeNotifications = {
  'model/retryChanged': ModelRetry,
  'model/retryQuotaChanged': RetryQuota,
  'runtime/requestSettled': z.object({ trackingId: z.string().min(1).max(128) }).strict(),
  'runtime/executionState': z.object({
    threadId: z.string().min(1),
    turns: z.array(z.object({ id: z.string().min(1), status: z.enum(['inProgress', 'completed', 'failed', 'interrupted']) }).strict()).max(256),
  }).strict(),
  'skills/usageFinished': z.object({ instanceId: z.string(), revisionId: z.string(), threadId: z.string(), turnId: z.string(), sourceType: z.literal('draft'), invocationId: z.string(), invocation: z.enum(['explicit', 'implicit']), occurredAt: z.number(), status: z.enum(['completed', 'failed', 'interrupted']), effectiveStepCompleted: z.boolean() }).strict(),
  'skills/telemetryEvent': SkillTelemetryEvent,
  'skills/testStarted': z.object({ instanceId: z.string(), revisionId: z.string(), threadId: z.string(), turnId: z.string(), sourceType: z.enum(['folder', 'zip', 'git', 'draft', 'bundled']).optional(), invocation: z.enum(['explicit', 'implicit']).optional(), invocationId: z.string().optional(), occurredAt: z.number().optional() }).strict(),
  'skills/invocationRecorded': z.object({ instanceId: z.string(), revisionId: z.string(), threadId: z.string(), turnId: z.string(), sourceType: z.enum(['folder', 'zip', 'git', 'draft']), invocation: z.enum(['explicit', 'implicit']), invocationId: z.string().optional(), occurredAt: z.number().optional() }).strict(),
  'skills/creationEntry': z.object({ entry: z.literal('C'), threadId: z.string(), turnId: z.string() }).strict(),
  'skills/usageCompleted': z.object({ instanceId: z.string(), revisionId: z.string(), sourceType: z.enum(['folder', 'zip', 'git', 'draft', 'bundled']), scope: z.string(), threadId: z.string(), turnId: z.string().nullable(), nodeId: z.string(), invocation: z.enum(['explicit', 'implicit']), invocationId: z.string().optional(), occurredAt: z.number().optional() }).strict(),
  'skills/draftValidation': z.object({ success: z.boolean(), issueCodes: z.array(z.string().max(80)).max(100), issueCount: z.number().int().nonnegative() }).strict(),
  'skills/draftChanged': SkillDraft,
  'skills/captureEvaluated': z.object({ threadId: z.string().min(1), turnId: z.string().min(1), outcome: z.enum(['shown', 'gate-missed']), suggestion: SkillCaptureSuggestion.optional() }).strict(),
  'skills/installProgress': SkillInstallation,
  'skills/installationChanged': z.object({ instanceId: z.string(), revisionId: z.string().optional(), action: z.enum(['installed', 'updated', 'uninstalled']), target: z.unknown().optional() }),
  'workspace/modelUpdated': z.object({
    assetId: z.string(),
    name: z.string(),
    file: ModelFile,
    workspace: Workspace,
    threadId: z.string().optional(),
    turnId: z.string().optional(),
    note: z.string().optional(),
  }),
  'workspace/updated': z.object({ workspace: Workspace }),
  'workspace/removed': z.object({ assetId: z.string() }),
  'artifact/registered': z.object({ artifact: Artifact }),
  'workflow/graphUpdated': WorkflowGraph,
  'print/statusChanged': z.object({ printJob: PrintJob }),
  'runtime/blenderProgress': z.object({
    threadId: z.string().optional(),
    turnId: z.string().optional(),
    message: z.string(),
    /** 0-1；无可靠来源时为 null */
    progress: z.number().min(0).max(1).nullable(),
  }),
  'blender/installProgress': BlenderStatus,
  'runtime/hi3dProgress': z.object({
    assetId: z.string(),
    threadId: z.string(),
    turnId: z.string(),
    callId: z.string().optional(),
    taskId: z.string().optional(),
    /** AI 为本次生成任务提供的目标/对象名称；保持原语言与大小写。 */
    targetName: z.string().min(1).max(80).optional(),
    /** 由 Runtime 根据实际 Hi3D action/kind 判断，不由 AI 拼接展示文案。 */
    generationType: z.enum(['image', 'model']).optional(),
    state: z.enum(['created', 'queueing', 'processing', 'success', 'failed']),
    message: z.string(),
    /** 查询接口未承诺数值进度；有可靠值时为 0-1，否则为 null。 */
    progress: z.number().min(0).max(1).nullable(),
    /** 查询异常时保留上次进度，允许用户关闭提示。 */
    stale: z.boolean().optional(),
  }),
  /** 严格保持 {"tag4": ...}，供 Desktop 直接消费。 */
  'runtime/imageClassification': ImageClassificationResult,
} as const;

export type RuntimeNotificationName = keyof typeof runtimeNotifications;
export type RuntimeNotificationParams<N extends RuntimeNotificationName> = z.infer<
  (typeof runtimeNotifications)[N]
>;

export function isRuntimeNotification(method: string): method is RuntimeNotificationName {
  return Object.prototype.hasOwnProperty.call(runtimeNotifications, method);
}
